    def __init__(self, name, initial_traits):
        self.name = name
        self.traits = {trait: weight for trait, weight in initial_traits.items()}
        self.trait_weights = {trait: weight for trait, weight in initial_traits.items()}  # 用于生成回复
        self.memory = []  # 对话历史
        self.responses = {
