            "suspicious": ["Who are you?", "I'm not sure I can trust you."],
            "happy": ["Great to see you!", "I'm feeling great today!"],
            "angry": ["I'm not in the mood for this!", "Why are you bothering me?"],
            "sad": ["I'm not feeling well...", "I could use some cheering up."]
        }
        self.context = {}  # 对话上下文

    def normalize_traits(self):
        total = sum(self.trait_weights.values())
        self.trait_weights = {trait: weight / total for trait, weight in self.trait_weights.items()}

    def update_traits(self, input_text):
        # Adjust traits based on input text
        adjustments = {
            "happy": 0.1, "sad": -0.1, "angry": 0.2
        }
        for emotion, adjustment in adjustments.items():
            if emotion in input_text.lower():
                for trait in self.traits:
                    self.traits[trait] += self.traits[trait] * adjustment
        self.normalize_traits()

    def process_feedback(self, feedback, dominant_trait):
        # Adjust traits based on feedback
        if feedback == "positive":
            self.traits[dominant_trait] += 0.05  # Increase the dominant trait for positive feedback
        elif feedback == "negative":
            self.traits[dominant_trait] -= 0.05  # Decrease the dominant trait for negative feedback
        self.normalize_traits()

    def learn_from_interaction(self, input_text, feedback):
        # Learn from the interaction by updating traits and processing feedback
        self.update_traits(input_text)
        dominant_trait = max(self.traits, key=self.traits.get)
        self.process_feedback(feedback, dominant_trait)
        self.memory.append((input_text, dominant_trait, feedback))  # 记录对话历史

    def generate_response(self):
        # Generate a response based on the current traits and context
        dominant_trait = max(self.trait_weights, key=self.trait_weights.get)
